    // Home - About
    "home.section.about.title": "About AdaptEd Russia",
    "home.section.about.heading": "Who’s behind AdaptEd Russia",
    "home.section.about.author.title": "Founder of AdaptEd Russia",
    "home.section.about.author.subtitle": "former international student",
    "home.section.about.author.fact1": "Studied at a Russian university",
    "home.section.about.author.fact2": "From first arrival to graduation",
    "home.section.about.summary": "I went through the full journey as an international student in Russia — from arrival to graduation. I know the documents, deadlines, and stress of unclear answers. AdaptEd Russia exists to make it easier for you.",
    "home.section.about.experience.title": "Experience",
    "home.section.about.experience.p1": "I studied in Russia as an international student and went through the whole journey,",
    "home.section.about.experience.p2.prefix": "from my first arrival",
    "home.section.about.experience.highlight": "to graduation",
    "home.section.about.experience.p2.suffix": ".",
    "home.section.about.experience.p3": "I know what it feels like: confusing documents, deadlines, stress, and a lot of questions with no clear answers.",
    "home.section.about.purpose.title": "Why AdaptEd Russia was created",
    "home.section.about.purpose.intro": "That’s why I built AdaptEd Russia — to make things easier for others.",
    "home.section.about.purpose.bullet1": "understand the education system in plain language",
    "home.section.about.purpose.bullet2": "not miss important deadlines",
    "home.section.about.purpose.bullet3": "navigate documents with confidence",
    "home.section.about.purpose.bullet4": "get help in their own language",
    "home.section.about.purpose.support": "Today I grow the project together with alumni, mentors, and experts in international education.",
    "home.section.about.closing": "AdaptEd Russia — adaptation without stress",
    "home.section.about.badge.alumni": "Graduates of Russian universities",
    "home.section.about.p1": "I’m a former international student who went through the whole journey: from the first flight to Russia to defending my diploma. I remember being lost in terms like “zachyotka”, “GOST”, “migration registration”... Searching where to extend my insurance, how to write applications for residence permits, and simply trying to understand what the department expected from me.",
    "home.section.about.p2": "That’s when the idea of AdaptEd Russia was born — not just an informational website, but a reliable assistant that’s always at hand: answering questions in your language, reminding you about deadlines, helping with documents — and doing all this clearly, without bureaucratic jargon.",
    "home.section.about.p3": "Right now I run the project personally — with support from mentors, alumni and experts in international education. The plan is to grow the team, including regional coordinators and university partners. Because every student deserves a calm start in a new country.",
    "home.section.about.p4": "Together — adaptation without stress.",
    
