    "home.section.about.summary": "J’ai vécu tout le parcours d’étudiant étranger en Russie — de l’arrivée au diplôme. Je connais les documents, les échéances et le stress des réponses floues. AdaptEd Russia existe pour vous simplifier la vie.",
    "home.section.about.experience.title": "Parcours",
    "home.section.about.experience.p1": "J’ai étudié en Russie comme étudiant étranger et j’ai traversé tout le parcours,",
    "home.section.about.experience.p2.prefix": "de mon arrivée en Russie",
    "home.section.about.experience.highlight": "jusqu’au diplôme",
    "home.section.about.experience.p2.suffix": ".",
    "home.section.about.experience.p3": "Je sais ce que c’est : des documents compliqués, des échéances, du stress et beaucoup de questions sans réponse claire.",
    "home.section.about.purpose.title": "Pourquoi AdaptEd Russia a été créé",
    "home.section.about.purpose.intro": "C’est pour cela que j’ai créé AdaptEd Russia — pour que ce soit plus simple pour les autres.",
    "home.section.about.purpose.bullet1": "comprendre le système éducatif en langage simple",
    "home.section.about.purpose.bullet2": "ne pas manquer les échéances importantes",
    "home.section.about.purpose.bullet3": "gérer les documents en confiance",
    "home.section.about.purpose.bullet4": "recevoir de l’aide dans leur langue",
    "home.section.about.purpose.support": "Aujourd’hui, je développe le projet avec des diplômés, des mentors et des experts de l’éducation internationale.",
    "home.section.about.closing": "AdaptEd Russia — une adaptation sans stress",
    "home.section.about.badge.alumni": "Diplômés des universités russes",
    "home.section.about.p1": "Je suis un ancien étudiant étranger qui a vécu tout le parcours : du premier vol vers la Russie jusqu’à la soutenance du diplôme. Je me souviens comment je me perdais dans des termes comme « zachotka », « GOST », « enregistrement migratoire »… Comment je cherchais où prolonger l’assurance, comment écrire les demandes pour le séjour, comment simplement comprendre ce que la faculté attendait de moi.",
    "home.section.about.p2": "C’est à ce moment-là qu’est née l’idée d’AdaptEd Russia — pas juste un site d’information, mais un véritable assistant fiable, toujours à portée de main : il répond à tes questions dans ta langue, rappelle les échéances, aide avec les documents — et fait tout cela de façon claire, sans jargon bureaucratique.",
    "home.section.about.p3": "Aujourd’hui, je porte le projet moi-même — avec le soutien de mentors, d’anciens étudiants et d’experts de l’éducation internationale. À terme, l’objectif est d’élargir l’équipe avec des coordinateurs régionaux et des partenaires parmi les universités. Parce que chaque étudiant mérite un départ serein dans un nouveau pays.",
    "home.section.about.p4": "Ensemble — une adaptation sans stress.",
    
